/* ---------------- STATE ---------------- */
let basket = {};      // {productId: qty}
let currentCat = 'all';
let searchTerm = '';
let user = null;      // {name}

/* ---------------- VIEW SWITCHING ---------------- */
function showView(id) {
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  const target = document.getElementById('view-' + id);
  if (target) target.classList.add('active');
  document.querySelectorAll('nav.links button').forEach(b => b.classList.toggle('active', b.dataset.view === id));
  document.getElementById('navLinks').classList.remove('open');
  window.scrollTo({ top: 0, behavior: 'instant' in window ? 'instant' : 'auto' });
  closeUserMenu();
}

/* ---------------- RENDER: HOME CATEGORY GRID ---------------- */
function renderHomeCats() {
  const grid = document.getElementById('homeCatGrid');
  grid.innerHTML = categories.map(c => `
    <button class="cat-card" onclick="goToCategory('${c.id}')">
      <div class="icon">${icons[c.id]}</div>
      <h3>${c.emoji} ${c.name}</h3>
      <span>${c.desc}</span>
    </button>
  `).join('');
}

function goToCategory(catId) {
  currentCat = catId;
  showView('order');
  renderTabs();
  renderProducts();
}

const bakeryImages = document.querySelectorAll('.bakery-slider img');

let currentImage = 0;

setInterval(() => {
  bakeryImages[currentImage].style.opacity = '0';

  currentImage = (currentImage + 1) % bakeryImages.length;

  bakeryImages[currentImage].style.opacity = '1';
}, 5000);
/* ---------------- RENDER: ORDER TABS ---------------- */
function renderTabs() {
  const bar = document.getElementById('tabBar');
  const all = [{ id: 'all', name: 'All', emoji: '🧺' }, ...categories];
  bar.innerHTML = all.map(c => `
    <button class="tab ${currentCat === c.id ? 'active' : ''}" onclick="selectCat('${c.id}')">${c.emoji || ''} ${c.name}</button>
  `).join('');
}
function selectCat(id) {
  currentCat = id;
  renderTabs();
  renderProducts();
}

/* ---------------- RENDER: PRODUCT GRID ---------------- */
function renderProducts() {
  const grid = document.getElementById('productGrid');
  let list = products.filter(p => currentCat === 'all' || p.cat === currentCat);
  if (searchTerm.trim()) {
    const t = searchTerm.trim().toLowerCase();
    list = list.filter(p => p.name.toLowerCase().includes(t));
  }
  if (list.length === 0) {
    grid.innerHTML = `<div class="no-results" style="grid-column:1/-1;">No items match "${escapeHtml(searchTerm)}". Try another search or category.</div>`;
    return;
  }
  grid.innerHTML = list.map(p => {
    const qty = basket[p.id] || 0;
    return `
    <div class="product-card" onclick="openProduct(${p.id})">
      <div class="product-img">${p.img ? `<img src="${p.img}" alt="${p.name}" style="width:100%;height:100%;object-fit:cover;">` : icons[p.cat]}</div>
      <div class="product-body">
        <div>
          <h3>${p.name}</h3>
          <span class="product-tag">${p.unit}</span>
        </div>
        <div class="product-foot">
          <span class="price">Rs ${p.price}</span>
          <div class="qty-stepper">
            <button
  onclick="event.stopPropagation(); stepQty(${p.id}, -1)"
  aria-label="Decrease quantity"
>
  −
</button>

<span id="qty-${p.id}">${qty || 1}</span>

<button
  onclick="event.stopPropagation(); stepQty(${p.id}, 1)"
  aria-label="Increase quantity"
>
  +
</button>
          </div>
        </div>
        <button
  class="add-btn" id="add-${p.id}" onclick="event.stopPropagation(); addToBasket(${p.id})">Add to basket</button>
      </div>
    </div>`;
  }).join('');
}

const pendingQty = {};
function stepQty(id, delta) {
  const current = pendingQty[id] || 1;
  const next = Math.max(1, current + delta);
  pendingQty[id] = next;
  document.getElementById('qty-' + id).textContent = next;
}

function addToBasket(id) {
  const qty = pendingQty[id] || 1;
  basket[id] = (basket[id] || 0) + qty;
  pendingQty[id] = 1;
  document.getElementById('qty-' + id).textContent = 1;
  const btn = document.getElementById('add-' + id);
  btn.textContent = 'Added ✓';
  btn.classList.add('added');
  setTimeout(() => { btn.textContent = 'Add to basket'; btn.classList.remove('added'); }, 1100);
  updateBasketUI();
  showToast('Added to basket');
}

/* ---------------- PRODUCT DETAILS ---------------- */

let selectedProduct = null;
let detailQty = 1;

function openProduct(id) {
  const product = products.find(p => p.id === id);

  if (!product) return;

  selectedProduct = product;
  detailQty = 1;

  /* ===== CUSTOM CAKE VIDEO ===== */

  const customCakeVideo = document.getElementById('customCakeVideo');
  const videoPlayer = document.getElementById('customCakeVideoPlayer');

  const redVelvetVideo = document.getElementById('redVelvetVideo');
  const redVelvetVideoPlayer = document.getElementById('redVelvetVideoPlayer');

  const truffleVideo = document.getElementById('truffleVideo');
  const truffleVideoPlayer = document.getElementById('truffleVideoPlayer');

  if (customCakeVideo) {
    if (product.id === 3) {
      customCakeVideo.style.display = 'block';

      if (videoPlayer) {
        videoPlayer.currentTime = 0;
        videoPlayer.play().catch(() => { });
      }
    } else {
      customCakeVideo.style.display = 'none';

      if (videoPlayer) {
        videoPlayer.pause();
      }
    }
  }

  /* ===== RED VELVET CAKE VIDEO ===== */

  if (product.name.toLowerCase().includes('red velvet')) {

    redVelvetVideo.style.display = 'block';

    if (redVelvetVideoPlayer) {
      redVelvetVideoPlayer.currentTime = 0;
      redVelvetVideoPlayer.play().catch(() => { });
    }

  } else {

    redVelvetVideo.style.display = 'none';

    if (redVelvetVideoPlayer) {
      redVelvetVideoPlayer.pause();
    }
  }

  /* ===== CHOCOLATE TRUFFLE VIDEO ===== */

if (product.id === 1) {
  truffleVideo.style.display = 'block';

  if (truffleVideoPlayer) {
    truffleVideoPlayer.currentTime = 0;
    truffleVideoPlayer.play().catch(() => {});
  }
} else {
  truffleVideo.style.display = 'none';

  if (truffleVideoPlayer) {
    truffleVideoPlayer.pause();
  }
}

  /* ===== PRODUCT INFORMATION ===== */

  const category = categories.find(c => c.id === product.cat);

  document.getElementById('detailImage').src = product.img;
  document.getElementById('detailImage').alt = product.name;

  document.getElementById('detailCategory').textContent =
    category ? category.name : 'Ittefaq Bakers';

  document.getElementById('detailName').textContent = product.name;

  document.getElementById('detailPrice').textContent =
    `PKR ${product.price.toLocaleString()}`;

  document.getElementById('detailQty').textContent = detailQty;

  document.getElementById('detailDescription').textContent =
    `Enjoy our freshly prepared ${product.name}, made with quality ingredients and carefully crafted for a delicious bakery experience. ${product.unit ? `Available as ${product.unit}.` : ''
    }`;

  showView('product');
}

function changeDetailQty(change) {
  detailQty = Math.max(1, detailQty + change);

  document.getElementById('detailQty').textContent = detailQty;
}


function addDetailToBasket() {
  if (!selectedProduct) return;

  basket[selectedProduct.id] =
    (basket[selectedProduct.id] || 0) + detailQty;

  updateBasketUI();

  const btn = document.getElementById('detailAddBtn');

  btn.textContent = 'ADDED ✓';
  btn.classList.add('added');

  showToast(`${selectedProduct.name} added to basket`);

  setTimeout(() => {
    btn.textContent = 'ADD TO BASKET';
    btn.classList.remove('added');
  }, 1100);
}


/* Product detail Add to Basket button */
document
  .getElementById('detailAddBtn')
  ?.addEventListener('click', addDetailToBasket);

/* ---------------- SEARCH ---------------- */
function onSearch(val) {
  searchTerm = val;
  renderProducts();
}

/* ---------------- BASKET UI ---------------- */
function basketCount() {
  return Object.values(basket).reduce((a, b) => a + b, 0);
}
function basketTotal() {
  return Object.entries(basket).reduce((sum, [id, qty]) => {
    const p = products.find(x => x.id == id);
    return sum + (p ? p.price * qty : 0);
  }, 0);
}
function updateBasketUI() {
  const count = basketCount();
  const total = basketTotal();
  const badge = document.getElementById('basketBadge');
  if (count > 0) { badge.style.display = 'flex'; badge.textContent = count; } else { badge.style.display = 'none'; }
  const bar = document.getElementById('basketBar');
  if (count > 0) {
    bar.classList.add('show');
    document.getElementById('basketBarText').textContent = `${count} item${count > 1 ? 's' : ''} · Rs ${total}`;
  } else {
    bar.classList.remove('show');
  }
}
function openBasket() {
  renderBasketPanel();
  document.getElementById('basketOverlay').classList.add('show');
}
function closeBasket() {
  document.getElementById('basketOverlay').classList.remove('show');
}
function renderBasketPanel() {
  const itemsEl = document.getElementById('basketItems');
  const footEl = document.getElementById('basketFooter');
  const entries = Object.entries(basket).filter(([, q]) => q > 0);
  if (entries.length === 0) {
    itemsEl.innerHTML = `<div class="basket-empty">Your basket is empty. Add something sweet.</div>`;
    footEl.innerHTML = '';
    return;
  }
  itemsEl.innerHTML = entries.map(([id, qty]) => {
    const p = products.find(x => x.id == id);
    return `
    <div class="basket-item">
      <div class="thumb">${p.img ? `<img src="${p.img}" alt="${p.name}" style="width:100%;height:100%;object-fit:cover;border-radius:10px;">` : icons[p.cat]}</div>
      <div class="info">
        <h4>${p.name}</h4>
        <span>Rs ${p.price} × ${qty}</span>
      </div>
      <div class="qty-stepper">
        <button onclick="basketStep(${id}, -1)" aria-label="Decrease">−</button>
        <span>${qty}</span>
        <button onclick="basketStep(${id}, 1)" aria-label="Increase">+</button>
      </div>
    </div>`;
  }).join('');

  const total = basketTotal();
  footEl.innerHTML = `
    <div class="basket-total-row"><span>Total</span><span>Rs ${total}</span></div>
    <button class="checkout-btn" onclick="openCheckoutForm()">
      Continue to order details
    </button>
    <p class="basket-note">Next, tell us where and when — then we'll send it to the shop on WhatsApp.</p>
  `;
}
function basketStep(id, delta) {
  basket[id] = Math.max(0, (basket[id] || 0) + delta);
  if (basket[id] === 0) delete basket[id];
  renderBasketPanel();
  updateBasketUI();
  renderProducts();
}

/* ---------------- CHECKOUT DETAILS FORM ---------------- */
function openCheckoutForm() {
  if (basketCount() === 0) return;
  closeBasket();
  document.getElementById('checkoutForm').reset();
  document.getElementById('checkoutFormWrap').style.display = 'block';
  document.getElementById('checkoutReady').style.display = 'none';
  toggleDeliveryFields();
  const dateInput = document.getElementById('co-date');
  const today = new Date().toISOString().split('T')[0];
  dateInput.min = today;
  document.getElementById('checkoutOverlay').classList.add('show');
}
function closeCheckoutForm() {
  document.getElementById('checkoutOverlay').classList.remove('show');
}
function toggleDeliveryFields() {
  const isDelivery = document.getElementById('co-fulfilment').value === 'Home delivery';
  const wrap = document.getElementById('deliveryFields');
  wrap.style.display = isDelivery ? 'block' : 'none';
  document.getElementById('co-city').required = isDelivery;
  document.getElementById('co-address').required = isDelivery;
}
function handleCheckoutSubmit(e) {
  e.preventDefault();
  const entries = Object.entries(basket).filter(([, q]) => q > 0);
  if (entries.length === 0) { showToast('Your basket is empty'); return false; }

  const fulfilment = document.getElementById('co-fulfilment').value;
  const date = document.getElementById('co-date').value;
  const isDelivery = fulfilment === 'Home delivery';
  const city = isDelivery ? document.getElementById('co-city').value.trim() : '';
  const address = isDelivery ? document.getElementById('co-address').value.trim() : '';
  const total = basketTotal();

  const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec'];
  function formatDateNice(iso) {
    if (!iso) return '';
    const d = new Date(iso + 'T00:00:00');
    return `${weekdays[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]}, ${d.getFullYear()}`;
  }
  const divider = '----------------------------------------';

  let msg = `*NEW ORDER - Ittefaq Bakers & Sweets*\n${divider}\n`;
  msg += `*Items:*\n`;
  msg += entries.map(([id, qty]) => {
    const p = products.find(x => x.id == id);
    return `• ${p.name} (${p.unit}) x${qty} — Rs ${p.price * qty}`;
  }).join('\n');
  msg += `\n\n*Delivery Details:*\n`;
  msg += `• Fulfilment: ${fulfilment}\n`;
  if (isDelivery) {
    msg += `• City: ${city}\n`;
    msg += `• Address: ${address}\n`;
  }
  msg += `• Date: ${formatDateNice(date)}\n`;
  msg += `\n*Estimated Total:* Rs ${total}\n`;
  msg += `${divider}\n`;
  msg += `Hi Ittefaq Bakers & Sweets! I would like to place this order. Please confirm availability.`;

  const waUrl = `https://wa.me/923452111846?text=${encodeURIComponent(msg)}`;
  document.getElementById('waLink').href = waUrl;
  document.getElementById('checkoutFormWrap').style.display = 'none';
  document.getElementById('checkoutReady').style.display = 'block';
  return false;
}
function backToCheckoutForm() {
  document.getElementById('checkoutReady').style.display = 'none';
  document.getElementById('checkoutFormWrap').style.display = 'block';
}
function afterWhatsAppTap() {
  closeCheckoutForm();
  showToast('Opening WhatsApp…');
}

/* ---------------- CONTACT PAGE MESSAGE FORM ---------------- */
function handleContactSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('cm-name').value.trim();
  const contact = document.getElementById('cm-contact').value.trim();
  const message = document.getElementById('cm-message').value.trim();

  const divider = '----------------------------------------';
  let msg = `*NEW MESSAGE - Ittefaq Bakers & Sweets*\n${divider}\n`;
  msg += `*From:* ${name}\n`;
  msg += `*Contact:* ${contact}\n`;
  msg += `*Message:*\n${message}\n`;
  msg += `${divider}\n`;
  msg += `Hi Ittefaq Bakers & Sweets, I have a question.`;

  const waUrl = `https://wa.me/923452111846?text=${encodeURIComponent(msg)}`;
  document.getElementById('contactWaLink').href = waUrl;
  document.getElementById('contactFormWrap').style.display = 'none';
  document.getElementById('contactReady').style.display = 'block';
  return false;
}
function backToContactForm() {
  document.getElementById('contactReady').style.display = 'none';
  document.getElementById('contactFormWrap').style.display = 'block';
}
function afterContactWhatsAppTap() {
  showToast('Opening WhatsApp…');
  setTimeout(() => {
    document.getElementById('contactForm').reset();
    backToContactForm();
  }, 600);
}

/* ---------------- LOGIN / SIGNUP (UI only, in-memory) ---------------- */
function switchAuthTab(which) {
  document.getElementById('tabLogin').classList.toggle('active', which === 'login');
  document.getElementById('tabSignup').classList.toggle('active', which === 'signup');
  document.getElementById('loginForm').style.display = which === 'login' ? 'block' : 'none';
  document.getElementById('signupForm').style.display = which === 'signup' ? 'block' : 'none';
}
function handleAuth(e, mode) {
  e.preventDefault();
  let name = 'Friend';
  if (mode === 'signup') {
    name = document.getElementById('su-name').value.trim() || 'Friend';
  } else {
    const contact = document.getElementById('li-contact').value.trim();
    name = contact.split('@')[0] || 'Friend';
  }
  user = { name };
  document.getElementById('authForms').style.display = 'none';
  document.getElementById('authSuccess').classList.add('show');
  document.getElementById('authSuccessMsg').textContent = mode === 'signup'
    ? `Account created. Welcome, ${name}.`
    : `Welcome back, ${name}.`;
  refreshUserChip();
  showToast(mode === 'signup' ? 'Account created' : 'Logged in');
  return false;
}
function refreshUserChip() {
  const label = document.getElementById('loginChipLabel');
  const accountBtn = document.getElementById('accountBtn');
  if (user) {
    label.textContent = user.name;
    accountBtn.style.display = 'block';
    document.getElementById('loginChip').onclick = toggleUserMenu;
  } else {
    label.textContent = 'Log in';
    accountBtn.style.display = 'none';
  }
}
function toggleUserMenu() {
  if (!user) { showView('login'); return; }
  document.getElementById('userDropdown').classList.toggle('open');
}
function closeUserMenu() {
  document.getElementById('userDropdown').classList.remove('open');
}
function logout() {
  user = null;
  refreshUserChip();
  closeUserMenu();
  document.getElementById('authForms').style.display = 'block';
  document.getElementById('authSuccess').classList.remove('show');
  document.getElementById('loginForm').reset();
  document.getElementById('signupForm').reset();
  showToast('Logged out');
  showView('home');
}
document.addEventListener('click', function (e) {
  const menu = document.getElementById('userMenu');
  if (menu && !menu.contains(e.target)) closeUserMenu();
});

/* ---------------- TOAST ---------------- */
let toastTimer;
function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove('show'), 1800);
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
}

/* ---------------- INIT ---------------- */
renderHomeCats();
renderTabs();
renderProducts();
updateBasketUI();
refreshUserChip();
document.querySelector('nav.links button[data-view="home"]').classList.add('active');

/* ---------------- FOOTER NAVIGATION ---------------- */
document.querySelectorAll('[data-nav]').forEach(link => {
  link.addEventListener('click', function (e) {
    e.preventDefault();

    const view = this.dataset.nav;
    showView(view);
  });
});

function setupCategoryScrollAnimation() {
  const categoryGrid = document.querySelector("#homeCatGrid");

  if (!categoryGrid) return;

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        const cards = entry.target.querySelectorAll(".cat-card");

        if (entry.isIntersecting) {
          // Cards enter from bottom one by one
          cards.forEach((card, index) => {
            setTimeout(() => {
              card.classList.add("cat-show");
            }, index * 150);
          });
        } else {
          // Reset cards when you scroll away
          cards.forEach((card) => {
            card.classList.remove("cat-show");
          });
        }
      });
    },
    {
      threshold: 0.2
    }
  );

  observer.observe(categoryGrid);
}

setupCategoryScrollAnimation();
